// 最后一轮：三项目 --skip 续跑直到 align-check 通过
import { spawnSync } from "child_process";
import fs from "fs";
import path from "path";

const BASE = "C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration";
const SCRIPTS = path.join(BASE, "scripts");
const SNAPSHOT = "D:\\repository\\skills\\scripts\\snapshot-openviking-memory.mjs";
const PROJECTS = ["苏住房C", "产品2.0", "门户"];

function run(args, label) {
  console.log(`\n=== ${label} ===`);
  const r = spawnSync(process.execPath, args, { cwd: BASE, stdio: "inherit" });
  return r.status ?? 1;
}

let fail = 0;
for (const project of PROJECTS) {
  const doneFile = path.join(process.env.TEMP, `done-${project}.json`);
  const args = [path.join(BASE, "import-to-ov.mjs"), project, "--batch=4", "--gap=5000"];
  if (fs.existsSync(doneFile)) args.push(`--skip=${doneFile}`);
  const st = run(args, `import ${project}`);
  if (st !== 0) fail++;
}

const align = run([path.join(SCRIPTS, "align-check.mjs")], "align check");
if (align === 2) {
  console.log("仍有缺口，见 out/align-report.json");
  fail++;
} else if (align !== 0) fail++;

run([path.join(SCRIPTS, "dedupe-memories-report.mjs")], "dedupe report");

console.log("\n=== snapshot ===");
const snap = spawnSync(process.execPath, [SNAPSHOT, "--commit", "--push", "--reason", "align-final"], {
  cwd: "D:\\repository\skills",
  stdio: "inherit",
});
if (snap.status !== 0) fail++;

process.exit(fail ? 1 : 0);
